import{_ as s,c as e,o as i,aA as n}from"./chunks/framework.B4Q5Ksnf.js";const g=JSON.parse('{"title":"Regions of Italy","description":"","frontmatter":{},"headers":[],"relativePath":"examples/italy.md","filePath":"examples/italy.md","lastUpdated":null}'),t={name:"examples/italy.md"};function p(l,a,o,r,h,c){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="Regions-of-Italy" tabindex="-1">Regions of Italy <a class="header-anchor" href="#Regions-of-Italy" aria-label="Permalink to &quot;Regions of Italy {#Regions-of-Italy}&quot;">​</a></h1><p>This example shows how to get data from a source and plot it using GeoMakie. It&#39;s more to show how to hybridize two data sources than anything else.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CairoMakie, GeoMakie</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GADM, DataFrames</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GeometryOps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GO</span></span></code></pre></div><p>Acquire the data via <a href="https://github.com/JuliaGeo/GADM.jl" target="_blank" rel="noreferrer">GADM.jl</a>, a package which allows access to the GADM dataset of country border geometries. We&#39;ll get the 1st level of detail, which provides the admin-1 (state) borders.</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ita_df = GADM.get(&quot;ITA&quot;; depth = 1) |&gt; DataFrame</span></span></code></pre></div><p>We can also calculate the centroid of Italy from this data!</p><p>Choosing a projection for the map is important, of course, and for a country like Italy, we can get away with an orthographic projection, which is kind of like an overhead view from a great distance.</p><p>We can center this orthographic projection at the centroid of Italy, so that distortion is minimized.</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ita_centroid = GO.centroid(ita_df.geom)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fig = Figure()</span></span>
<span class="line"><span>ga = GeoAxis(</span></span>
<span class="line"><span>    fig[1, 1];</span></span>
<span class="line"><span>    dest = &quot;+proj=ortho +lon_0=$(ita_centroid[1]) +lat_0=$(ita_centroid[2])&quot;</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>poly!(</span></span>
<span class="line"><span>    ga, ita_df.geom;</span></span>
<span class="line"><span>    color = 1:size(ita_df, 1), # this could be any vector of length \`size(ita_df, 1)\`</span></span>
<span class="line"><span>    strokecolor = :blue, strokewidth = 1, shading = NoShading</span></span>
<span class="line"><span>    )</span></span>
<span class="line"><span>fig</span></span></code></pre></div><p>That looks like a lot of ticks. Let&#39;s simplify the grid:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ga.xticks = Makie.WilkinsonTicks(5; k_min = 3)</span></span>
<span class="line"><span>ga.yticks = Makie.WilkinsonTicks(10; k_min = 5)</span></span>
<span class="line"><span>fig</span></span></code></pre></div><p>Whoops, this doesn&#39;t cover the whole of Italy! No worries, we&#39;ll have a spine eventually to show this.</p><hr><p><em>This page was generated using <a href="https://github.com/fredrikekre/Literate.jl" target="_blank" rel="noreferrer">Literate.jl</a>.</em></p>`,14)])])}const k=s(t,[["render",p]]);export{g as __pageData,k as default};
